// snapshot -> predict -> reconcile-or-rollback, fully deterministic
function mutate(state, optimistic, serverResult) {
  const snapshot = { ...state };            // 1. snapshot for rollback
  let s = { ...state, ...optimistic };      // 2. apply prediction locally
  if (serverResult.ok) {
    s = { ...s, ...serverResult.value };    // 3a. reconcile: replace prediction with server truth
  } else {
    s = snapshot;                           // 3b. rollback to snapshot
  }
  return s;
}

// optimistic 'pending' echo; server assigns the real order number (unpredictable)
const created = mutate(
  { orderNo: null, status: 'idle' },
  { orderNo: 'temp', status: 'pending' },
  { ok: true, value: { orderNo: 7741, status: 'confirmed' } }
);

// failure path: server rejects -> roll back to the pre-action snapshot
const failed = mutate(
  { orderNo: null, status: 'idle' },
  { orderNo: 'temp', status: 'pending' },
  { ok: false }
);

console.log('created=' + created.orderNo + '/' + created.status);
console.log('failed=' + failed.orderNo + '/' + failed.status);
